import type { BankQuestion } from "@/lib/bank";

/** Magnetism, EMI and AC (Physics (JEE/NEET)): 128 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id":"phy-magnetism-emi-1","question":"A charged particle moves parallel to a uniform magnetic field. The magnetic force on it is:","options":["Maximum","Zero","qvB directed along the field","qvB directed opposite to the field"],"answer":1,"explanation":"F = qvB sin θ and θ = 0° for motion along the field, so the force is zero and the particle keeps moving in a straight line. The force is maximum (qvB) when the velocity is perpendicular to B.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-magnetism-emi-2","question":"The SI unit of magnetic flux is:","options":["Tesla","Weber","Henry","Gauss"],"answer":1,"explanation":"Magnetic flux Φ = B·A is measured in weber (Wb); 1 Wb = 1 T·m². Tesla is the unit of flux density B and henry is the unit of inductance.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-magnetism-emi-3","question":"In an ideal step-up transformer:","options":["The secondary has fewer turns than the primary","The output voltage and output current are both higher than the input","The output voltage is higher and the output current is lower than the input","The output power is higher than the input power"],"answer":2,"explanation":"V_s/V_p = N_s/N_p > 1 for a step-up transformer, and for an ideal transformer V_pI_p = V_sI_s, so a higher voltage comes with a proportionately lower current. Power is never increased.","difficulty":"easy","source":"JEE Main · NEET"},
  {"id":"phy-magnetism-emi-4","question":"A circular coil of one turn and radius 5 cm carries a current of 5 A. The magnetic field at its centre is (μ₀ = 4π × 10⁻⁷ T·m/A):","options":["2π × 10⁻⁵ T","π × 10⁻⁵ T","4π × 10⁻⁵ T","2π × 10⁻⁶ T"],"answer":0,"explanation":"B = μ₀I/(2R) = 4π × 10⁻⁷ × 5 / (2 × 0.05) = 4π × 10⁻⁷ × 50 = 2π × 10⁻⁵ T ≈ 6.3 × 10⁻⁵ T.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-magnetism-emi-5","question":"A long straight wire carries a current of 10 A. The magnetic field at a perpendicular distance of 2 cm from the wire is:","options":["10⁻⁵ T","10⁻⁴ T","2 × 10⁻⁴ T","5 × 10⁻⁵ T"],"answer":1,"explanation":"B = μ₀I/(2πr) = 2 × 10⁻⁷ × 10 / 0.02 = 10⁻⁴ T. Using r in centimetres gives an answer 100 times too small.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-magnetism-emi-6","question":"A straight conductor of length 0.5 m carries a current of 2 A and is placed perpendicular to a uniform magnetic field of 0.2 T. The force on it is:","options":["0.1 N","0.2 N","0.4 N","2 N"],"answer":1,"explanation":"F = BIl sin 90° = 0.2 × 2 × 0.5 = 0.2 N, directed perpendicular to both the current and the field (Fleming's left-hand rule).","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-magnetism-emi-7","question":"The magnetic flux linked with each turn of a 100-turn coil changes by 2 mWb in 0.1 s. The average emf induced in the coil is:","options":["0.2 V","2 V","20 V","0.02 V"],"answer":1,"explanation":"|ε| = N ΔΦ/Δt = 100 × 2 × 10⁻³ / 0.1 = 2 V. Forgetting the number of turns gives 0.02 V.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-magnetism-emi-8","question":"An alternating voltage is given by V = 200 sin(100πt) volt. Its rms value and frequency are:","options":["200 V, 100 Hz","141 V, 100 Hz","141 V, 50 Hz","100 V, 50 Hz"],"answer":2,"explanation":"V_rms = V₀/√2 = 200/√2 ≈ 141 V. ω = 100π rad/s gives f = ω/2π = 50 Hz. The peak value 200 V is not the rms value.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-magnetism-emi-9","question":"The energy stored in a 2 H inductor carrying a steady current of 3 A is:","options":["3 J","6 J","9 J","18 J"],"answer":2,"explanation":"U = ½LI² = ½ × 2 × 3² = 9 J, stored in the magnetic field of the inductor.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-magnetism-emi-10","question":"A proton and an α-particle having the same kinetic energy enter a uniform magnetic field perpendicularly. The ratio of the radii of their circular paths (proton : α) is:","options":["1 : 2","1 : √2","2 : 1","1 : 1"],"answer":3,"explanation":"r = mv/(qB) = √(2mK)/(qB) ∝ √m/q for the same K. Proton: √1/1 = 1; α-particle: √4/2 = 1. The ratio is 1 : 1 (the trap is to use r ∝ m/q, which gives 1 : 2).","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-magnetism-emi-11","question":"A metal rod of length 0.5 m slides at 10 m/s on smooth rails perpendicular to a uniform field of 0.2 T. The rails are joined through a 0.5 Ω resistor (rod and rails have negligible resistance). The force needed to keep the rod moving at constant speed is:","options":["0.1 N","1 N","0.4 N","0.2 N"],"answer":3,"explanation":"Motional emf = Blv = 0.2 × 0.5 × 10 = 1 V, so I = 1/0.5 = 2 A. The magnetic force on the rod opposes the motion with F = BIl = 0.2 × 2 × 0.5 = 0.2 N, and an equal external force keeps the speed constant. Check: F·v = 2 W = I²R.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-magnetism-emi-12","question":"A long solenoid has 1000 turns per metre and carries a current of 2 A. The magnetic field inside it is (μ₀ = 4π × 10⁻⁷ T·m/A):","options":["2.5 × 10⁻³ T","1.26 × 10⁻³ T","2.5 × 10⁻⁴ T","8 × 10⁻⁴ T"],"answer":0,"explanation":"B = μ₀nI = 4π × 10⁻⁷ × 1000 × 2 = 8π × 10⁻⁴ ≈ 2.5 × 10⁻³ T. The field is uniform inside and independent of the solenoid's radius.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-magnetism-emi-13","question":"The current through a 0.5 H inductor changes uniformly from +2 A to −2 A in 0.1 s. The magnitude of the self-induced emf is:","options":["10 V","0 V","5 V","20 V"],"answer":3,"explanation":"ΔI = 2 − (−2) = 4 A (the current reverses, so the change is 4 A, not 0 or 2 A). |ε| = L ΔI/Δt = 0.5 × 4/0.1 = 20 V.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-magnetism-emi-14","question":"A series LCR circuit has L = 10 mH and C = 1 μF. Its resonant angular frequency is:","options":["10² rad/s","10³ rad/s","10⁴ rad/s","10⁵ rad/s"],"answer":2,"explanation":"ω₀ = 1/√(LC) = 1/√(10 × 10⁻³ × 10⁻⁶) = 1/√(10⁻⁸) = 10⁴ rad/s (about 1.6 kHz). The resistance does not affect the resonant frequency.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-magnetism-emi-15","question":"An ideal transformer has 1000 turns in the primary and 100 turns in the secondary. The primary is connected to 220 V AC and the secondary to a 2 Ω resistor. The current drawn from the supply is:","options":["11 A","110 A","0.11 A","1.1 A"],"answer":3,"explanation":"V_s = 220 × 100/1000 = 22 V, so I_s = 22/2 = 11 A. For an ideal transformer V_pI_p = V_sI_s: I_p = 22 × 11/220 = 1.1 A (equivalently I_p = I_s × N_s/N_p).","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-magnetism-emi-16","question":"A coil of resistance 30 Ω and inductive reactance 40 Ω is connected to a 200 V (rms) AC supply. The average power consumed is:","options":["800 W","640 W","1333 W","480 W"],"answer":3,"explanation":"Z = √(30² + 40²) = 50 Ω, so I_rms = 200/50 = 4 A. Power is dissipated only in R: P = I²R = 16 × 30 = 480 W. Equivalently P = V_rms I_rms cos φ with cos φ = 30/50 = 0.6.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-magnetism-emi-17","question":"Two long parallel wires 10 cm apart each carry a current of 10 A in the same direction. The force per unit length between them is:","options":["2 × 10⁻⁴ N/m, attractive","2 × 10⁻⁴ N/m, repulsive","2 × 10⁻⁵ N/m, attractive","4 × 10⁻⁴ N/m, repulsive"],"answer":0,"explanation":"F/l = μ₀I₁I₂/(2πd) = 2 × 10⁻⁷ × 10 × 10 / 0.1 = 2 × 10⁻⁴ N/m. Parallel currents attract; antiparallel currents repel.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-magnetism-emi-18","question":"A rectangular coil of 100 turns and area 10 cm² carries a current of 2 A. It is placed in a uniform field of 0.5 T with its plane parallel to the field. The torque on the coil is:","options":["Zero","0.01 N·m","1 N·m","0.1 N·m"],"answer":3,"explanation":"τ = NIAB sin θ, where θ is the angle between the magnetic moment (normal to the plane) and B. With the plane parallel to B, θ = 90°: τ = 100 × 2 × 10 × 10⁻⁴ × 0.5 = 0.1 N·m. The torque would be zero with the plane perpendicular to the field.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-magnetism-emi-19","question":"How many of the following statements about electromagnetic induction are correct? (A) Lenz's law is a consequence of the law of conservation of energy. (B) Laminating the core of a transformer reduces eddy-current losses. (C) A bar magnet dropped through a vertical copper tube falls with an acceleration less than g. (D) The emf induced in a loop depends on the resistance of the loop.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"(A), (B) and (C) are correct. (D) is wrong: ε = −dΦ/dt is fixed by the rate of change of flux alone; only the induced current (ε/R) depends on the resistance.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-magnetism-emi-20","question":"A proton (take q/m = 10⁸ C/kg) passes undeflected through a region with crossed fields E = 10⁴ V/m and B = 0.1 T. It then enters a region with only the same magnetic field B = 0.1 T, perpendicular to its velocity. The radius of its circular path is:","options":["1 cm","1 mm","10 cm","1 m"],"answer":0,"explanation":"Undeflected motion requires qE = qvB, so v = E/B = 10⁴/0.1 = 10⁵ m/s (velocity selector). Then r = mv/(qB) = v/((q/m)B) = 10⁵/(10⁸ × 0.1) = 10⁻² m = 1 cm.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-magnetism-emi-21","question":"A charged particle enters a uniform magnetic field with its velocity making an angle of 45° with the field. The ratio of the pitch of its helical path to the radius of the helix is:","options":["2π","π","π/2","4π"],"answer":0,"explanation":"Radius r = mv sin θ/(qB) and pitch p = (v cos θ)T = v cos θ × 2πm/(qB). So p/r = 2π cot θ = 2π cot 45° = 2π. The result is independent of the speed and the field.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-22","question":"A 100 μF capacitor charged to 10 V is connected across a 10 mH inductor of negligible resistance. The maximum current in the resulting LC oscillation is:","options":["1 A","0.1 A","10 A","0.01 A"],"answer":0,"explanation":"Energy is conserved: ½CV₀² = ½LI₀², so I₀ = V₀√(C/L) = 10 × √(100 × 10⁻⁶ / 10 × 10⁻³) = 10 × √(10⁻²) = 10 × 0.1 = 1 A. The oscillation frequency is 1/(2π√(LC)) ≈ 159 Hz.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-magnetism-emi-23","question":"A metal rod of length 0.5 m rotates with angular speed 40 rad/s about one end in a plane perpendicular to a uniform magnetic field of 0.4 T. The emf induced between the ends of the rod is:","options":["1 V","8 V","4 V","2 V"],"answer":3,"explanation":"Different points of the rod move with different speeds, so ε = ∫Bωr dr from 0 to l = ½Bωl² = ½ × 0.4 × 40 × (0.5)² = 2 V. Using Blv with v = ωl (the tip speed) gives double the correct value.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-magnetism-emi-24","question":"A 2 H inductor and a 4 Ω resistor are connected in series to a 12 V battery at t = 0. The time after which the current reaches half of its final value is (ln 2 = 0.693):","options":["0.25 s","0.35 s","0.5 s","0.69 s"],"answer":1,"explanation":"Time constant τ = L/R = 0.5 s and I = I₀(1 − e^(−t/τ)). Setting I = I₀/2 gives e^(−t/τ) = ½, so t = τ ln 2 = 0.5 × 0.693 ≈ 0.35 s. The final current is 3 A; at t = τ the current is 63% of it, not 50%.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-25","question":"Assertion (A): A capacitor blocks direct current but allows alternating current to pass. Reason (R): Capacitive reactance X_C = 1/(ωC) becomes infinite as the frequency tends to zero.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"For DC, ω = 0 and X_C → ∞, so in the steady state no current flows; for AC the finite reactance permits current. R is exactly the reason for A. An inductor behaves the opposite way (X_L = ωL).","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-magnetism-emi-26","question":"Match the AC circuit element (List I) with the phase relation between the current and the applied voltage (List II). List I: (P) pure resistor; (Q) pure inductor; (R) pure capacitor; (S) series LCR circuit at resonance. List II: (1) current leads voltage by 90°; (2) current lags voltage by 90°; (3) current in phase with voltage.","options":["P-3, Q-1, R-2, S-3","P-3, Q-2, R-1, S-3","P-3, Q-2, R-1, S-2","P-2, Q-3, R-1, S-3"],"answer":1,"explanation":"In a resistor current and voltage are in phase; in an inductor the current lags by 90°; in a capacitor it leads by 90°; at resonance X_L = X_C so the circuit is purely resistive and the phase difference is zero.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-magnetism-emi-27","question":"The current in the primary of a pair of coupled coils falls uniformly from 5 A to zero in 0.01 s, inducing an average emf of 100 V in the secondary. If the secondary circuit has a total resistance of 10 Ω, the charge that flows through it during this time is:","options":["0.05 C","0.1 C","0.2 C","1 C"],"answer":1,"explanation":"Mutual inductance M = ε/(ΔI/Δt) = 100/(5/0.01) = 0.2 H. Charge flowed q = (total flux change)/R = MΔI/R = 0.2 × 5/10 = 0.1 C. Equivalently, I = 100/10 = 10 A for 0.01 s gives 0.1 C.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-28","question":"A coil of 100 turns, each of area 0.01 m², rotates at 100 rad/s about an axis in its plane that is perpendicular to a uniform field of 0.1 T. The rms value of the emf generated is:","options":["10 V","7.07 V","14.1 V","5 V"],"answer":1,"explanation":"ε = NBAω sin ωt, so the peak emf is ε₀ = 100 × 0.1 × 0.01 × 100 = 10 V and ε_rms = ε₀/√2 ≈ 7.07 V. This is the principle of the AC generator.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-magnetism-emi-29","question":"A long solid cylindrical conductor of radius R carries a current I distributed uniformly over its cross-section. The ratio of the magnetic field at a distance R/2 from the axis to that at a distance 2R from the axis is:","options":["1 : 4","1 : 2","1 : 1","2 : 1"],"answer":2,"explanation":"By Ampere's law, inside: B = μ₀Ir/(2πR²), so at r = R/2, B = μ₀I/(4πR). Outside: B = μ₀I/(2πr), so at r = 2R, B = μ₀I/(4πR). The ratio is 1 : 1. The field is maximum at the surface r = R.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-magnetism-emi-30","question":"In a series LCR circuit the rms voltages across the resistor, inductor and capacitor are 40 V, 50 V and 20 V respectively. The rms voltage of the source is:","options":["110 V","70 V","50 V","30 V"],"answer":2,"explanation":"V_L and V_C are 180° apart, so their net is 50 − 20 = 30 V, which is 90° out of phase with V_R. V = √(V_R² + (V_L − V_C)²) = √(40² + 30²) = 50 V. Simply adding the three readings (110 V) ignores the phase differences.","difficulty":"very-hard","source":"JEE Main · NEET"},
  {"id":"phy-magnetism-emi-31","question":"The SI unit of self-inductance is the:","options":["tesla","weber","farad","henry"],"answer":3,"explanation":"1 henry = 1 V s/A = 1 Wb/A. The weber is the unit of magnetic flux, the tesla of magnetic field and the farad of capacitance.","difficulty":"easy","source":"NEET pattern"},
  {"id":"phy-magnetism-emi-32","question":"A proton (take q/m = 10⁸ C/kg) moves in a cyclotron with a magnetic field of 0.2π T. The frequency of the oscillator needed for resonance is:","options":["1 MHz","20 MHz","100 MHz","10 MHz"],"answer":3,"explanation":"f = qB/(2πm) = 10⁸ × 0.2π/(2π) = 10⁷ Hz = 10 MHz. It does not depend on the speed or radius of the proton (non-relativistic).","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-magnetism-emi-33","question":"The magnetic flux through a single loop varies as Φ = (5t² + 3t) Wb, with t in seconds. The magnitude of the induced emf at t = 2 s is:","options":["13 V","20 V","26 V","23 V"],"answer":3,"explanation":"|e| = dΦ/dt = 10t + 3 = 23 V at t = 2 s. 26 V is the flux itself at that instant, not its rate of change.","difficulty":"moderate","source":"NEET pattern"},
  {"id":"phy-magnetism-emi-34","question":"A wire carrying current I is bent into a circular arc of radius r subtending 90° at the centre. The magnetic field at the centre due to the arc is:","options":["μ₀I/2r","μ₀I/(4πr)","μ₀I/8r","μ₀I/4r"],"answer":2,"explanation":"A full loop gives μ₀I/2r, and an arc gives that times θ/2π. For 90°: (μ₀I/2r) × (1/4) = μ₀I/8r.","difficulty":"moderate","source":"JEE Main · NEET"},
  {"id":"phy-magnetism-emi-35","question":"In a moving-coil galvanometer the number of turns is doubled, which also doubles the coil's resistance. Its current sensitivity and voltage sensitivity become:","options":["unchanged and doubled","doubled and unchanged","doubled and doubled","halved and unchanged"],"answer":1,"explanation":"Current sensitivity = NBA/k doubles with N. Voltage sensitivity = NBA/(kR); both N and R double, so it is unchanged.","difficulty":"hard","source":"NEET pattern"},
  {"id":"phy-magnetism-emi-36","question":"A proton (take q/m = 10⁸ C/kg) is accelerated from rest through 5 kV and then enters a uniform magnetic field of 0.05 T perpendicular to its velocity. The radius of its circular path is:","options":["40 cm","2 cm","10 cm","20 cm"],"answer":3,"explanation":"v = √(2(q/m)V) = √(2 × 10⁸ × 5000) = 10⁶ m/s. r = v/((q/m)B) = 10⁶/(10⁸ × 0.05) = 0.2 m = 20 cm.","difficulty":"hard","source":"JEE Main · NEET"},
  {"id":"phy-magnetism-emi-37","question":"A series LCR circuit with R = 10 Ω and X_L = X_C = 50 Ω is connected to a 200 V (rms) AC supply. The rms voltage across the inductor is:","options":["1000 V","50 V","400 V","200 V"],"answer":0,"explanation":"At resonance Z = R, so I = 200/10 = 20 A, and V_L = IX_L = 20 × 50 = 1000 V, much larger than the supply voltage. V_C is equal and opposite, so they cancel in the total.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-38","question":"The current in a circuit is i = 3 + 4 sin ωt ampere. Its rms value is:","options":["5 A","√12.5 A","7 A","√17 A"],"answer":3,"explanation":"Mean of i² = 9 + 24⟨sin ωt⟩ + 16⟨sin²ωt⟩ = 9 + 0 + 8 = 17, so I_rms = √17 A ≈ 4.1 A. 5 A wrongly combines the DC and peak AC parts as if they were perpendicular.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-39","question":"A current I flows in a square loop of side a. The magnetic field at the centre of the loop is:","options":["4μ₀I/(πa)","√2 μ₀I/(πa)","2√2 μ₀I/(πa)","μ₀I/(2√2 πa)"],"answer":2,"explanation":"Each side is at distance a/2 and subtends 45° on each side: B = (μ₀I/4π(a/2))(sin45° + sin45°) = √2 μ₀I/(2πa). Four sides give 2√2 μ₀I/(πa).","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-40","question":"A proton (take q/m = 10⁸ C/kg) moving at 10⁶ m/s enters, perpendicularly, a region 5 cm wide containing a uniform magnetic field of 0.1 T perpendicular to its velocity. The angle through which it is deflected on leaving the region is:","options":["30°","60°","45°","90°"],"answer":0,"explanation":"Radius r = v/((q/m)B) = 10⁶/10⁷ = 0.1 m = 10 cm. Since the width (5 cm) is less than r, the proton crosses the region with sinθ = d/r = 0.5, i.e. θ = 30°.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-magnetism-emi-41","question":"How many of the following statements about magnetic materials are correct?\n(A) Diamagnetic substances have a small negative susceptibility.\n(B) The susceptibility of a paramagnetic substance varies inversely with absolute temperature.\n(C) A ferromagnetic substance becomes paramagnetic above its Curie temperature.\n(D) Superconductors are perfect paramagnets.","options":["Only one","Only two","Only three","All four"],"answer":2,"explanation":"A, B (Curie's law) and C are correct. D is wrong: superconductors expel magnetic fields completely (Meissner effect), so they are perfect diamagnets (χ = −1). So only three are correct.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-magnetism-emi-42","question":"An inductor L carrying current I₀ is suddenly connected across a resistor R (the battery being removed). The time after which the energy stored in the inductor falls to half its initial value is:","options":["(2L/R) ln 2","(L/R) ln 2","(L/2R) ln 2","L/R"],"answer":2,"explanation":"I = I₀e^(−Rt/L) and U ∝ I², so U = U₀e^(−2Rt/L). Setting this to U₀/2 gives t = (L/2R) ln 2. (L/R) ln 2 is the time for the current to halve.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-magnetism-emi-43","question":"A conducting rod of length 1 m slides without friction on horizontal rails joined by a 2 Ω resistor, in a vertical magnetic field of 0.5 T. A constant horizontal force of 0.5 N pulls the rod. Neglecting other resistances, its terminal speed is:","options":["2 m/s","8 m/s","1 m/s","4 m/s"],"answer":3,"explanation":"At terminal speed the magnetic force B²l²v/R balances F: v = FR/(B²l²) = 0.5 × 2/(0.25 × 1) = 4 m/s.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-44","question":"A step-down transformer with 80% efficiency supplies 4.4 kW at 220 V. Its primary is connected to an 1100 V supply. The current in the primary is:","options":["5 A","25 A","20 A","4 A"],"answer":0,"explanation":"Input power = 4400/0.8 = 5500 W, so the primary current = 5500/1100 = 5 A. Assuming 100% efficiency gives 4 A.","difficulty":"very-hard","source":"NEET pattern"},
  {"id":"phy-magnetism-emi-45","question":"Assertion (A): The average power consumed in a purely inductive AC circuit is zero.\nReason (R): In a purely inductive circuit the current and the voltage are in phase.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":2,"explanation":"A is true, but R is false: the current lags the voltage by 90°, so the power factor cos 90° is zero. Energy stored in the field during one quarter-cycle is returned in the next.","difficulty":"very-hard","source":"NEET pattern"},
  {"id": "phy-magnetism-emi-46", "question": "Two long parallel straight wires carry currents in opposite directions. The wires:", "options": ["attract each other", "exert no force on each other", "repel each other", "attract or repel depending on the size of the currents"], "answer": 2, "explanation": "Parallel currents attract and antiparallel currents repel, F/l = μ₀I₁I₂/2πd, with the direction set only by the relative current directions, not by their size.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-magnetism-emi-47", "question": "Which of the following is true of magnetic field lines?", "options": ["They always form closed loops", "They start from the north pole and end on the south pole", "They can intersect where the field is strong", "They exist only outside a magnet"], "answer": 0, "explanation": "Since there are no magnetic monopoles (div B = 0), field lines have no beginning or end: they run N to S outside a magnet and S to N inside it, forming closed loops. They never intersect.", "difficulty": "easy", "source": "NEET pattern"},
  {"id": "phy-magnetism-emi-48", "question": "A circular coil of 50 turns and radius 10 cm carries a current of 2 A. Its magnetic dipole moment is about:", "options": ["0.0314 A m²", "31.4 A m²", "6.28 A m²", "3.14 A m²"], "answer": 3, "explanation": "m = NIA = 50 × 2 × π(0.1)² = π ≈ 3.14 A m². Using the circumference (6.28) instead of the area is the usual slip.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-magnetism-emi-49", "question": "The inductive reactance of a 0.1 H inductor at a frequency of 50 Hz is about:", "options": ["5 Ω", "31.4 Ω", "3.14 Ω", "314 Ω"], "answer": 1, "explanation": "X_L = 2πfL = 2π × 50 × 0.1 ≈ 31.4 Ω. 5 Ω forgets the 2π (it uses f instead of ω).", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-magnetism-emi-50", "question": "At resonance, a series LCR circuit has:", "options": ["power factor 0 and impedance zero", "power factor 1 and impedance equal to R", "power factor 1 and maximum impedance", "power factor 0.5 and impedance equal to √2 R"], "answer": 1, "explanation": "At resonance X_L = X_C, so Z = R (its minimum), the current is in phase with the voltage, and cos φ = R/Z = 1.", "difficulty": "moderate", "source": "JEE Main · NEET"},
  {"id": "phy-magnetism-emi-51", "question": "A bar magnet of magnetic moment 2 A m² lies in a uniform magnetic field of 0.5 T with its axis at 30° to the field. The torque on it is:", "options": ["1 N m", "0.87 N m", "0.25 N m", "0.5 N m"], "answer": 3, "explanation": "τ = mB sin θ = 2 × 0.5 × sin 30° = 0.5 N m. 0.87 N m uses cos 30°.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-magnetism-emi-52", "question": "At a place, the horizontal component of the Earth's magnetic field is 0.3 G and the vertical component is 0.3√3 G. The angle of dip there is:", "options": ["60°", "30°", "45°", "90°"], "answer": 0, "explanation": "tan δ = B_V/B_H = √3, so δ = 60°. 30° comes from inverting the ratio.", "difficulty": "moderate", "source": "NEET pattern"},
  {"id": "phy-magnetism-emi-53", "question": "A long straight wire carrying current I has a semicircular bend of radius r in it, the straight portions lying along a line through the centre of the semicircle. The magnetic field at that centre is:", "options": ["μ₀I/2r", "μ₀I/4πr", "μ₀I/4r", "μ₀I/2πr"], "answer": 2, "explanation": "The straight parts point straight at the centre (dl parallel to r), so they contribute nothing. The semicircle gives half of a full loop's μ₀I/2r, i.e. μ₀I/4r.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-magnetism-emi-54", "question": "A 100-turn coil of area 0.01 m² and total resistance 10 Ω lies perpendicular to a magnetic field of 0.5 T. The field is reduced to zero. The charge that flows through the coil is:", "options": ["0.5 C", "5 C", "depends on how quickly the field is reduced", "0.05 C"], "answer": 3, "explanation": "q = ∫I dt = NΔΦ/R = 100 × 0.5 × 0.01/10 = 0.05 C. The emf and current depend on the rate of change, but the total charge does not.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-magnetism-emi-55", "question": "A 30 Ω resistor and a capacitor of reactance 40 Ω are connected in series to an AC source. The current:", "options": ["lags the voltage by tan⁻¹(4/3) ≈ 53°", "leads the voltage by tan⁻¹(4/3) ≈ 53°", "leads the voltage by tan⁻¹(3/4) ≈ 37°", "is in phase with the voltage"], "answer": 1, "explanation": "Z = √(30² + 40²) = 50 Ω and tan φ = X_C/R = 4/3, so φ ≈ 53°. In a capacitive circuit the current leads the voltage; a lagging current would need an inductor.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-magnetism-emi-56", "question": "An aeroplane with a wingspan of 20 m flies horizontally at 200 m/s at a place where the vertical component of the Earth's field is 4 × 10⁻⁵ T. The emf induced between the wing tips is:", "options": ["1.6 V", "0.016 V", "0.16 V", "16 V"], "answer": 2, "explanation": "Only the vertical component is cut by the horizontally moving wings: ε = B_V l v = 4 × 10⁻⁵ × 20 × 200 = 0.16 V.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-magnetism-emi-57", "question": "A solenoid 0.5 m long with a cross-section of 10 cm² has 1000 turns (μ₀ = 4π × 10⁻⁷ T m/A). Its self-inductance is about:", "options": ["2.5 mH", "1.26 mH", "25 mH", "0.8 mH"], "answer": 0, "explanation": "L = μ₀N²A/l = 4π × 10⁻⁷ × 10⁶ × 10⁻³/0.5 = 8π × 10⁻⁴ ≈ 2.5 × 10⁻³ H. 1.26 mH forgets to divide by the 0.5 m length.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-magnetism-emi-58", "question": "A toroid of mean radius 10 cm has 500 turns and carries a current of 2 A (μ₀ = 4π × 10⁻⁷ T m/A). The magnetic field inside its core is:", "options": ["2π × 10⁻³ T", "4 × 10⁻³ T", "2 × 10⁻³ T", "1 × 10⁻³ T"], "answer": 2, "explanation": "By Ampère's law, B(2πr) = μ₀NI, so B = 4π × 10⁻⁷ × 500 × 2/(2π × 0.1) = 2 × 10⁻³ T. The field outside an ideal toroid is zero.", "difficulty": "hard", "source": "JEE Main · NEET"},
  {"id": "phy-magnetism-emi-59", "question": "For a sinusoidal alternating current, the ratio of its rms value to its average value over half a cycle is about:", "options": ["1.11", "1.41", "0.90", "1.57"], "answer": 0, "explanation": "I_rms = I₀/√2 and I_avg (half cycle) = 2I₀/π, so the ratio is π/(2√2) ≈ 1.11. 1.41 is the peak-to-rms ratio, and the full-cycle average is zero.", "difficulty": "hard", "source": "JEE Main pattern"},
  {"id": "phy-magnetism-emi-60", "question": "A closed loop carrying 4 A consists of two concentric semicircular arcs of radii 10 cm and 20 cm joined by two straight radial segments (μ₀ = 4π × 10⁻⁷ T m/A). The magnetic field at the common centre is about:", "options": ["1.9 × 10⁻⁵ T", "1.26 × 10⁻⁵ T", "zero", "6.3 × 10⁻⁶ T"], "answer": 3, "explanation": "The radial segments contribute nothing. Going round the loop, the two arcs carry current in opposite senses, so B = (μ₀I/4)(1/a − 1/b) = 4π × 10⁻⁷ × (10 − 5) = 2π × 10⁻⁶ ≈ 6.3 × 10⁻⁶ T. 1.9 × 10⁻⁵ T adds the arc fields instead of subtracting them.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-magnetism-emi-61", "question": "How many of the following statements about AC circuits are correct?\n(A) In a purely capacitive circuit the current leads the voltage by 90°.\n(B) The impedance of a series LCR circuit is minimum at resonance.\n(C) The quality factor of a series LCR circuit is ω₀L/R.\n(D) At resonance, a parallel LC circuit draws its maximum current from the supply.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "A, B and C are correct. D is wrong: an ideal parallel LC circuit at resonance has maximum impedance and draws minimum current, which is why it is called a rejector circuit. Three are correct.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-magnetism-emi-62", "question": "A horizontal metal rod of mass 0.1 kg and length 1 m slides down, without friction, along two long vertical conducting rails joined at the top by a 1 Ω resistor. A horizontal uniform magnetic field of 1 T is perpendicular to the plane of the rails (g = 10 m/s², other resistances negligible). The terminal speed of the rod is:", "options": ["10 m/s", "1 m/s", "0.1 m/s", "it keeps accelerating at g"], "answer": 1, "explanation": "At terminal speed the magnetic force B²l²v/R balances mg: v = mgR/(B²l²) = 0.1 × 10 × 1/1 = 1 m/s. Lenz's law means the induced current always opposes the fall.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-magnetism-emi-63", "question": "Assertion (A): A thick copper plate swinging between the poles of a strong magnet stops quickly, but the same plate with long slots cut in it swings for much longer.\nReason (R): The slots reduce the paths available to eddy currents, so the eddy currents and the damping they cause become much smaller.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "Both are true and R explains A: eddy currents in the solid plate dissipate its kinetic energy (electromagnetic damping). Slots break up the current loops, which is the same reason transformer cores are laminated.", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-magnetism-emi-64", "question": "A cyclotron accelerates protons (take q/m = 10⁸ C/kg) in a magnetic field of 1 T. The radius of the dees is 0.5 m. The maximum kinetic energy of the emerging protons is:", "options": ["25 MeV", "12.5 MeV", "6.25 MeV", "50 MeV"], "answer": 1, "explanation": "At the exit radius v = qBR/m, so KE = q²B²R²/2m. In electron-volts this is (q/m)B²R²/2 = 10⁸ × 1 × 0.25/2 = 1.25 × 10⁷ eV = 12.5 MeV, independent of the accelerating voltage.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-magnetism-emi-65", "question": "A square loop of side 10 cm carrying 5 A lies in the same plane as a long straight wire carrying 10 A. The nearer side of the loop is parallel to the wire, 10 cm from it, and carries current in the same direction (μ₀/2π = 2 × 10⁻⁷ T m/A). The net force on the loop is:", "options": ["1 × 10⁻⁵ N, towards the wire", "5 × 10⁻⁶ N, away from the wire", "zero", "5 × 10⁻⁶ N, towards the wire"], "answer": 3, "explanation": "Near side (parallel current, attracted): 2 × 10⁻⁷ × 10 × 5 × 0.1/0.1 = 1 × 10⁻⁵ N. Far side (antiparallel, repelled): the same over 0.2 m = 5 × 10⁻⁶ N. The forces on the perpendicular sides cancel, leaving 5 × 10⁻⁶ N towards the wire.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-magnetism-emi-66", "question": "Match the device (List I) with the principle on which it is based (List II).\nList I: (P) AC generator; (Q) transformer; (R) induction furnace; (S) choke coil.\nList II: (1) mutual induction; (2) self-induction, which limits current with little power loss; (3) heating by eddy currents; (4) emf induced in a coil rotating in a magnetic field.", "options": ["P-4, Q-1, R-3, S-2", "P-1, Q-4, R-3, S-2", "P-4, Q-2, R-3, S-1", "P-4, Q-1, R-2, S-3"], "answer": 0, "explanation": "The generator's rotating coil has a changing flux (4); a transformer couples two coils through mutual induction (1); an induction furnace melts metal with eddy-current heating (3); a choke's inductive reactance cuts the current with almost no I²R loss (2).", "difficulty": "very-hard", "source": "NEET pattern"},
  {"id": "phy-magnetism-emi-67", "question": "In an LC circuit with L = 10 mH and C = 100 μF, the capacitor is fully charged at t = 0. The energy is first shared equally between the capacitor and the inductor at:", "options": ["π/2 ms ≈ 1.57 ms", "2π ms ≈ 6.28 ms", "π/4 ms ≈ 0.79 ms", "1 ms"], "answer": 2, "explanation": "√(LC) = √(10⁻² × 10⁻⁴) = 10⁻³ s. q = Q₀ cos ωt, and the energies are equal when q = Q₀/√2, i.e. ωt = π/4, so t = (π/4)√(LC) = π/4 ms (one-eighth of the 2π ms period).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-magnetism-emi-68", "question": "A wire bent into a semicircle of radius 10 cm carries a current of 5 A in a uniform magnetic field of 0.2 T perpendicular to the plane of the semicircle. The net magnetic force on the wire is:", "options": ["0.1π N", "0.1 N", "zero", "0.2 N"], "answer": 3, "explanation": "In a uniform field the force on any wire equals that on the straight line joining its ends: F = BI(2R) = 0.2 × 5 × 0.2 = 0.2 N. 0.1π N uses the arc length πR instead of the chord.", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id": "phy-magnetism-emi-69", "question": "A small circular loop of radius r is placed at the centre of a large circular loop of radius R (R ≫ r), coaxially in the same plane. The mutual inductance of the pair is about:", "options": ["μ₀πR²/2r", "μ₀πr²/2R", "μ₀πr/2", "μ₀r²/2R"], "answer": 1, "explanation": "A current I in the large loop gives a nearly uniform field μ₀I/2R over the small loop, so the flux linked is (μ₀I/2R)πr² and M = μ₀πr²/2R. By reciprocity this M is the same whichever coil carries the current.", "difficulty": "very-hard", "source": "JEE Main · JEE Advanced"},
  {"id": "phy-magnetism-emi-70", "question": "A series circuit with R = 100 Ω, X_L = 200 Ω and X_C = 100 Ω is connected to a 200 V (rms) AC supply. The average power consumed is:", "options": ["400 W", "100 W", "200 W", "282 W"], "answer": 2, "explanation": "Z = √(100² + (200 − 100)²) = 100√2 Ω, so I = 200/(100√2) = √2 A and P = I²R = 2 × 100 = 200 W (power factor 1/√2). 400 W assumes resonance (Z = R).", "difficulty": "very-hard", "source": "JEE Main pattern"},
  {"id":"phy-magnetism-emi-71","question":"An electron (charge e, mass m) moves in a circular orbit. The ratio of the magnitude of its orbital magnetic moment to the magnitude of its orbital angular momentum is:","options":["e/(2m)","e/m","2e/m","e/(4πm)"],"answer":0,"explanation":"μ = IA = (ev/2πr)(πr²) = evr/2 and L = mvr, so μ/L = e/(2m), independent of the size of the orbit and of the speed. e/m (the spin value, roughly) is the usual slip.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-72","question":"A series LCR circuit has L = 0.1 H, C = 10 μF and R = 10 Ω. Its quality factor (sharpness of resonance) Q = ω₀L/R is:","options":["1","10","100","1000"],"answer":1,"explanation":"ω₀ = 1/√(LC) = 1/√(10⁻⁶) = 1000 rad/s, so Q = ω₀L/R = 1000 × 0.1/10 = 10; equivalently Q = (1/R)√(L/C) = (1/10)√(10⁴) = 10. Using ω₀ = 1000 but forgetting R gives 100.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-73","question":"A bar magnet is dropped vertically, along its length, through the centre of a fixed horizontal copper ring. Neglecting air resistance, its acceleration is:","options":["less than g while approaching the ring and greater than g while leaving it","less than g both while approaching and while leaving the ring","greater than g both while approaching and while leaving the ring","exactly g throughout, since copper is non-magnetic"],"answer":1,"explanation":"By Lenz's law the induced current always opposes the relative motion: approaching, the ring repels the magnet; leaving, the ring attracts it back. Both forces act upward, so a < g in both stages. 'Greater than g while leaving' forgets that the current reverses direction.","difficulty":"moderate","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-74","question":"A uniform wire is bent into a complete circle. Current I is led into the circle at point P and out at point Q by long straight radial wires, P and Q dividing the circumference into arcs in the ratio 1 : 2. The magnetic field at the centre due to the circular part is:","options":["μ₀I/(2r)","μ₀I/(6r)","zero","μ₀I/(3r)"],"answer":2,"explanation":"The arcs are in parallel, so the currents are inversely proportional to their lengths, while the field each arc gives at the centre is proportional to (current × length). The two products are equal and the fields are opposite, so they cancel; the radial leads add nothing at the centre. The answer is the same for any position of P and Q.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-75","question":"A thin non-conducting disc of radius R carries a uniform surface charge density σ and rotates about its axis with angular speed ω. The magnetic field at its centre is:","options":["μ₀σωR²/2","μ₀σωR","μ₀σωR/4","μ₀σωR/2"],"answer":3,"explanation":"A ring of radius r and width dr carries current dI = σ(2πr dr)(ω/2π) = σωr dr and gives dB = μ₀dI/(2r) = μ₀σω dr/2. Integrating from 0 to R: B = μ₀σωR/2. μ₀σωR²/2 has the wrong dimensions.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-76","question":"When the current in coil 1 changes at 10 A/s, an emf of 5 mV is induced in a nearby coil 2. When coil 2 carries a steady current of 2 A (coil 1 carrying none), the total flux linked with coil 1 is:","options":["1 mWb","0.5 mWb","2.5 mWb","it cannot be found without the number of turns of coil 1"],"answer":0,"explanation":"M = e/(di/dt) = 5 × 10⁻³/10 = 0.5 mH, and mutual inductance is the same both ways (M₁₂ = M₂₁). So the flux linkage of coil 1 is MI₂ = 0.5 mH × 2 A = 1 mWb. The turns are already included in M.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-77","question":"A 10 V battery of negligible internal resistance, a 2 Ω resistor and a switch are in series with a parallel combination of an ideal inductor and a 10 Ω resistor. After steady state is reached, the switch is opened. Just after the switch is opened, the voltage across the 10 Ω resistor is:","options":["10 V","50 V","zero","8.3 V"],"answer":1,"explanation":"In the steady state the ideal inductor shorts the 10 Ω resistor, so it carries 10/2 = 5 A. The inductor current cannot change instantly, so after opening the switch these 5 A circulate through the 10 Ω resistor: V = 5 × 10 = 50 V, larger than the battery's emf. Zero is the voltage before opening.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-78","question":"In an AC circuit the applied voltage is v = 100 sin ωt volt and the current is i = 2 cos(ωt − π/6) ampere. The average power consumed is:","options":["86.6 W","zero","50 W","100 W"],"answer":2,"explanation":"cos(ωt − π/6) = sin(ωt + π/3), so the current leads the voltage by 60°, not 30°. P = (1/2)V₀I₀ cos 60° = (1/2)(100)(2)(1/2) = 50 W. Reading the phase as π/6 gives 86.6 W.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-79","question":"A lamp rated 100 V, 500 W is to be run at its rated power from a 200 V (rms), 50 Hz supply, using a pure inductor in series with it. The inductance needed is about:","options":["0.20 H","0.064 H","0.13 H","0.11 H"],"answer":3,"explanation":"Lamp: R = 100²/500 = 20 Ω and I = 5 A, so Z = 200/5 = 40 Ω and X_L = √(40² − 20²) ≈ 34.6 Ω. L = 34.6/(2π × 50) ≈ 0.11 H. Subtracting voltages arithmetically (X_L = 20 Ω) gives 0.064 H; the voltages across R and L are 90° apart and add as phasors.","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-80","question":"A long straight hollow conducting tube has inner radius R and outer radius 2R and carries a current I distributed uniformly over its cross-section. The magnetic field at a distance 1.5R from the axis is:","options":["5μ₀I/(36πR)","μ₀I/(3πR)","μ₀I/(4πR)","zero"],"answer":0,"explanation":"Ampère's law: the enclosed current is I(r² − R²)/[(2R)² − R²] = I(2.25 − 1)/3 = 5I/12. B = μ₀(5I/12)/(2π × 1.5R) = 5μ₀I/(36πR). Ignoring the hollow core (enclosed current I × 2.25/4) gives μ₀I/(4πR), and taking the whole current gives μ₀I/(3πR).","difficulty":"hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-81","question":"A conducting rod of mass 0.1 kg and length 1 m can slide without friction on two horizontal rails that are joined at one end by an uncharged 0.1 F capacitor; a uniform vertical magnetic field of 1 T acts throughout. A constant horizontal force of 0.2 N pulls the rod from rest. Neglecting resistance, the rod moves with:","options":["acceleration 2 m/s²","acceleration 1 m/s²","a terminal velocity of 2 m/s","acceleration that decreases to zero"],"answer":1,"explanation":"The capacitor voltage equals the emf BLv, so q = CBLv and i = CBLa. The magnetic force BiL = B²L²Ca opposes F: F − B²L²Ca = ma, so a = F/(m + B²L²C) = 0.2/(0.1 + 0.1) = 1 m/s², constant. A terminal velocity would occur with a resistor, not a capacitor.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-82","question":"A metal rod of mass 0.1 kg and length 1 m slides without friction down a pair of parallel rails inclined at 30° to the horizontal. The rails are joined at the top by a 1.5 Ω resistor, and a uniform magnetic field of 0.5 T acts vertically. Neglecting other resistances (g = 10 m/s²), the terminal speed of the rod is:","options":["3.0 m/s","3.5 m/s","4.0 m/s","6.0 m/s"],"answer":2,"explanation":"Only the horizontal velocity component v cos θ cuts the vertical field: emf = BLv cos θ and I = BLv cos θ/R. The magnetic force BIL is horizontal, so its component up the incline is BIL cos θ. Balance: mg sin θ = B²L²v cos²θ/R, so v = 0.1 × 10 × 1.5 × 0.5/(0.25 × 0.75) = 4.0 m/s. Leaving out both cos θ factors gives 3.0 m/s.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-83","question":"A series LCR circuit with R = 100 Ω, L = 0.5 H and C = 2 μF is driven by a source of fixed voltage amplitude and variable frequency. The current amplitude falls to 1/√2 of its resonant value at two angular frequencies. Their difference is:","options":["1000 rad/s","100 rad/s","400 rad/s","200 rad/s"],"answer":3,"explanation":"At the half-power points |X_L − X_C| = R, which gives ω₂ − ω₁ = R/L = 100/0.5 = 200 rad/s exactly (ω₀ = 1/√(LC) = 1000 rad/s sits between them). Using R/2L = 100 rad/s gives the half-width, not the full bandwidth.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-84","question":"A proton (take q/m = 10⁸ C/kg) is released from rest in a region with a uniform electric field of 10⁴ V/m along +y and a uniform magnetic field of 0.1 T along +z. Neglecting gravity, the maximum speed it attains is:","options":["2 × 10⁵ m/s","1 × 10⁵ m/s","1.4 × 10⁵ m/s","it keeps increasing without limit"],"answer":0,"explanation":"The proton moves on a cycloid: its motion is a drift at E/B = 10⁵ m/s along x plus a circular motion of the same speed. The speeds add at the top of each arch, giving v_max = 2E/B = 2 × 10⁵ m/s, where it is farthest along the field. E/B is only the average drift speed.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-85","question":"A square loop of side 10 cm lies in the plane of a long straight wire carrying 10 A, with two sides parallel to the wire. The loop moves directly away from the wire at 5 m/s. At the instant its nearer side is 10 cm from the wire, the emf induced in the loop is (μ₀ = 4π × 10⁻⁷ T m/A):","options":["2.5 μV","5 μV","10 μV","zero, since the loop does not rotate"],"answer":1,"explanation":"The two parallel sides cut fields of different strength: emf = (μ₀I/2π)lv(1/x − 1/(x + l)) = 2 × 10⁻⁶ × 0.1 × 5 × (10 − 5) = 5 × 10⁻⁶ V. Taking only the nearer side (μ₀I/2πx)lv gives 10 μV; the far side's emf opposes it.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-86","question":"A uniform magnetic field confined to a long cylindrical region of radius R changes at a constant rate. The ratio of the magnitude of the induced electric field at a distance R/2 from the axis to that at a distance 3R is:","options":["1 : 6","1 : 1","3 : 2","2 : 3"],"answer":2,"explanation":"∮E·dl = −dΦ/dt. Inside (r < R): E·2πr = πr² dB/dt, so E = (r/2) dB/dt = (R/4) dB/dt at R/2. Outside, the flux stops growing with r: E·2πr = πR² dB/dt, so E = R²/(2r) dB/dt = (R/6) dB/dt at 3R. Ratio = 3 : 2. Assuming E = 0 outside, where B = 0, is the classic mistake.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-87","question":"A 100 Ω resistor and a capacitor of reactance 100√3 Ω are in series across a sinusoidal source. The voltage across the capacitor, compared with the source voltage:","options":["leads by 30°","lags by 60°","lags by 90°","lags by 30°"],"answer":3,"explanation":"The current leads the source voltage by φ with tan φ = X_C/R = √3, so φ = 60°. The capacitor voltage lags the current by 90°, so it lags the source by 90° − 60° = 30°. 60° is the current's lead, and 90° is the lag relative to the current, not the source.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-88","question":"How many of the following statements are correct?\n(A) The magnetic force on a moving charged particle does no work on it.\n(B) A charged particle passes undeflected through crossed uniform E and B fields when v = E/B, whatever the sign of its charge.\n(C) The frequency of revolution of a (non-relativistic) charged particle in a uniform magnetic field increases with its speed.\n(D) Two parallel beams of electrons moving side by side in vacuum attract each other because the magnetic attraction outweighs the electric repulsion.","options":["Only one","Only two","Only three","All four"],"answer":1,"explanation":"A is true (F ⊥ v). B is true: reversing the charge reverses both forces together. C is false: f = qB/2πm does not depend on speed. D is false: the magnetic force is (v²/c²) times the electric force, so for v < c the beams repel.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-89","question":"Assertion (A): A DC motor draws a much larger current at the moment it is switched on than when it is running at full speed.\nReason (R): The back emf in the armature is proportional to its speed of rotation, so it is zero when the armature is at rest.","options":["Both A and R are true and R is the correct explanation of A","Both A and R are true but R is not the correct explanation of A","A is true but R is false","A is false but R is true"],"answer":0,"explanation":"Current I = (V − e_back)/R. At start e_back = 0, so I = V/R, which is large because the armature resistance is small; as the motor speeds up the back emf rises and the current drops. That is why starters with series resistance are used. R explains A.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-90","question":"A current I flows in each arrangement. Match the location (List I) with the magnetic field there (List II).\nList I: (P) centre of a circular loop of radius R; (Q) centre of a semicircular arc of radius R whose two straight leads lie along the diameter through that centre; (R) a point at distance R from a very long straight wire; (S) a point at distance R from a semi-infinite straight wire, on the perpendicular to the wire through its end.\nList II: (1) μ₀I/(4πR); (2) μ₀I/(2πR); (3) μ₀I/(4R); (4) μ₀I/(2R).","options":["P-4, Q-3, R-2, S-1","P-4, Q-3, R-1, S-2","P-3, Q-4, R-2, S-1","P-4, Q-2, R-3, S-1"],"answer":0,"explanation":"Full loop: μ₀I/2R. Semicircle: half of that, μ₀I/4R, and leads pointing through the centre add nothing. Infinite wire: μ₀I/2πR. Semi-infinite wire at its end: half of the infinite-wire value, μ₀I/4πR.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-91","question":"Two coils placed near each other are connected in series. Their equivalent inductance is 0.5 H with one way of connecting them and 0.3 H when the connections of one coil are reversed. The mutual inductance between the coils is:","options":["0.2 H","0.05 H","0.1 H","0.4 H"],"answer":1,"explanation":"Series aiding: L₁ + L₂ + 2M = 0.5 H; series opposing: L₁ + L₂ − 2M = 0.3 H. Subtracting, 4M = 0.2 H, so M = 0.05 H. Taking 2M = 0.2 H, i.e. M = 0.1 H, forgets that each coil's flux links the other (the factor 2).","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-92","question":"An inductor L and a resistor R are connected in series to an ideal battery at t = 0. At the instant the current is one-third of its final value, the ratio of the power dissipated in the resistor to the rate at which energy is being stored in the inductor is:","options":["1 : 3","1 : 1","1 : 2","2 : 1"],"answer":2,"explanation":"At current i, the battery supplies Ei, the resistor takes i²R and the inductor takes L i di/dt = i(E − iR). With i = E/3R: i²R : i(E − iR) = iR : (E − iR) = (E/3) : (2E/3) = 1 : 2. The two are equal only when i is half the final current.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-93","question":"A current rises uniformly from 0 to I₀ and then drops instantly to 0, repeating this sawtooth pattern. A sinusoidal current has the same peak value I₀. The ratio of the heat produced by the sawtooth current to that produced by the sinusoidal current in the same resistor over the same long time is:","options":["1 : 2","1 : 1","3 : 2","2 : 3"],"answer":3,"explanation":"Heat ∝ mean of i². Sawtooth: mean of (I₀t/T)² over a period = I₀²/3 (rms I₀/√3). Sine: I₀²/2. Ratio = (1/3)/(1/2) = 2 : 3. Comparing average currents (I₀/2 against 2I₀/π) instead of mean squares gives a wrong answer.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-94","question":"A thin bar magnet oscillates in a uniform horizontal magnetic field with a period of 2 s. It is cut into two equal halves by a cut perpendicular to its length, and one half is made to oscillate in the same field. Its period is:","options":["1 s","2 s","0.5 s","√2 s"],"answer":0,"explanation":"T = 2π√(I/mB). Each half has half the magnetic moment (same pole strength, half the length) and moment of inertia (M/2)(L/2)²/12 = I/8. So T' = T√((1/8)/(1/2)) = T/2 = 1 s. A cut along the length halves both m and I, leaving T = 2 s, which is the trap.","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-95","question":"An electron with kinetic energy 10 eV moves in a circle perpendicular to a uniform magnetic field of 1 × 10⁻⁴ T. The magnitude of the magnetic moment of this circulating electron is:","options":["8 × 10⁻¹⁵ A m²","1.6 × 10⁻¹⁴ A m²","3.2 × 10⁻¹⁴ A m²","1.6 × 10⁻¹⁸ A m²"],"answer":1,"explanation":"μ = IA = (ev/2πr)(πr²) = evr/2, and r = mv/(eB), so μ = mv²/(2B) = KE/B = 1.6 × 10⁻¹⁸ J/10⁻⁴ T = 1.6 × 10⁻¹⁴ A m². Using mv²/B (dropping the 1/2) gives 3.2 × 10⁻¹⁴ A m².","difficulty":"very-hard","source":"JEE Main pattern"},
  {"id":"phy-magnetism-emi-96","question":"A charged particle moves through a region containing only a uniform magnetic field. The magnetic force on it:","options":["does work equal to qvB per unit distance","always increases its kinetic energy","acts along its velocity","does no work, so its speed stays constant"],"answer":3,"explanation":"F = qv × B is always perpendicular to v, so F·v = 0 and the force does no work. It can change the direction of motion but never the speed or kinetic energy.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-magnetism-emi-97","question":"Lenz's law, which fixes the direction of an induced current, is a consequence of the conservation of:","options":["momentum","charge","energy","magnetic flux"],"answer":2,"explanation":"If the induced current aided the change that produced it, the change would grow by itself and create energy from nothing. Opposing the change means work must be done to sustain it, as energy conservation requires.","difficulty":"easy","source":"JEE Main"},
  {"id":"phy-magnetism-emi-98","question":"A current I flows round a loop of wire in the shape of a regular hexagon of side a. The magnetic field at its centre is:","options":["3μ₀I/(πa)","√3μ₀I/(πa)","μ₀I/(2√3πa)","6μ₀I/(πa)"],"answer":1,"explanation":"Each side subtends ±30° at the centre, at perpendicular distance d = √3a/2. One side gives (μ₀I/4πd)(sin 30° + sin 30°) = μ₀I/(4πd) = μ₀I/(2√3πa). Six sides give 6μ₀I/(2√3πa) = √3μ₀I/(πa).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-magnetism-emi-99","question":"A wire of arbitrary shape lying in the xy-plane runs from the origin to the point (3 m, 4 m) and carries 2 A. It lies in a uniform magnetic field of 0.5 T along +z. The magnitude of the net magnetic force on the wire is:","options":["5 N","7 N","3.5 N","it depends on the shape of the wire"],"answer":0,"explanation":"In a uniform field, F = I(∫dl) × B, and ∫dl is just the straight displacement from start to end, of length 5 m perpendicular to B. So F = 2 × 5 × 0.5 = 5 N, whatever the shape.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-magnetism-emi-100","question":"A thin insulating rod of length L carries a charge q spread uniformly along it and rotates with angular speed ω about a perpendicular axis through ONE END. Its magnetic moment is:","options":["qωL²/6","qωL²/2","qωL²/12","qωL²/3"],"answer":0,"explanation":"An element dq = (q/L)dr at radius r acts as a current loop dI = dq·ω/2π of area πr², giving dM = (qω/2L)r² dr. Integrating from 0 to L: M = qωL²/6 (consistent with M = (q/2m)·L_angular, as I = mL²/3).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-magnetism-emi-101","question":"A very large flat conducting sheet carries a uniform surface current of K amperes per metre of width. The magnitude of the magnetic field near the sheet (on either side) is:","options":["μ₀K/2π","μ₀K","2μ₀K","μ₀K/2"],"answer":3,"explanation":"Apply Ampère's law to a rectangle straddling the sheet with sides of length l parallel to it: the field is parallel to the sheet, opposite on the two sides, so 2Bl = μ₀Kl and B = μ₀K/2, independent of the distance.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-magnetism-emi-102","question":"A coaxial cable has a central wire carrying current I and an outer cylindrical sheath carrying the same current I back. Which statement about the magnetic field is correct?","options":["B = μ₀I/(2πr) everywhere outside the central wire","B is zero between the conductors and μ₀I/(2πr) outside","Between the conductors B = μ₀I/(2πr); outside the cable B = 0","B is uniform between the conductors"],"answer":2,"explanation":"An Ampèrian circle between the conductors encloses only the inner current I, giving B = μ₀I/(2πr). Outside, it encloses I − I = 0, so B = 0. This is why coaxial cables do not radiate stray fields.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-magnetism-emi-103","question":"Two long straight insulated wires lie in the xy-plane along the x-axis and the y-axis, crossing at the origin without touching. Each carries current I, one in the +x direction and the other in the +y direction. The magnetic field at the point (a, a) in the same plane is:","options":["μ₀I/(πa), along +z","zero","μ₀I/(πa), along −z","μ₀I/(√2πa)"],"answer":1,"explanation":"Each wire is at distance a from the point and gives μ₀I/(2πa). The wire along x (current +x) gives a field along +z at a point with y > 0; the wire along y (current +y) gives a field along −z at a point with x > 0. They cancel.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-magnetism-emi-104","question":"A tangent galvanometer has a coil of 50 turns and radius 10 cm, set in the magnetic meridian where the horizontal component of the Earth's field is 3 × 10⁻⁵ T. The current that produces a deflection of 45° is about:","options":["0.19 A","0.095 A","0.048 A","0.95 A"],"answer":1,"explanation":"At 45°, the coil's field equals B_H: μ₀NI/(2r) = B_H. I = 2rB_H/(μ₀N) = 2 × 0.1 × 3 × 10⁻⁵/(4π × 10⁻⁷ × 50) ≈ 0.095 A.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-magnetism-emi-105","question":"A paramagnetic salt obeying Curie's law has magnetic susceptibility χ at 300 K. At 150 K its susceptibility is:","options":["2χ","χ/2","χ","4χ"],"answer":0,"explanation":"Curie's law: χ = C/T for a paramagnet. Halving the absolute temperature doubles the susceptibility, as thermal agitation disturbs the alignment of the dipoles less.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-magnetism-emi-106","question":"The core of a transformer is made of soft iron rather than steel because soft iron has:","options":["low permeability, reducing the flux","high retentivity, so it stays magnetised","high coercivity, so it resists demagnetisation","low coercivity and a narrow hysteresis loop, so little energy is lost per cycle"],"answer":3,"explanation":"In a transformer the core is magnetised back and forth 50 times a second. The energy lost per cycle equals the area of the hysteresis loop, so a material with a thin loop (low coercivity, high permeability) like soft iron is preferred. Steel suits permanent magnets.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-magnetism-emi-107","question":"A metal rod of length L rotates with angular speed ω in a plane perpendicular to a uniform magnetic field B, about an axis through its MIDPOINT. The potential difference between its two ends is:","options":["BωL²/8","BωL²/2","zero","BωL²/4"],"answer":2,"explanation":"Each half develops an emf of ½Bω(L/2)² = BωL²/8 between the centre and its end, and both ends are at the same potential relative to the centre (by symmetry). So the potential difference between the two ends is zero.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-magnetism-emi-108","question":"A horizontal metal rod of mass 0.1 kg and length 0.5 m falls from rest while sliding without friction between two long vertical conducting rails, which are connected at the top by an uncharged 0.4 F capacitor. A horizontal magnetic field of 1 T is perpendicular to the plane of the rails (g = 10 m/s²; neglect resistance). The rod's acceleration is:","options":["decreasing to zero (terminal velocity)","10 m/s²","5 m/s², constant","2.5 m/s², constant"],"answer":2,"explanation":"The capacitor voltage equals the motional emf BLv, so the current is i = CBL(dv/dt). The magnetic force BiL = CB²L²a opposes the fall: mg − CB²L²a = ma, so a = mg/(m + CB²L²) = 1/(0.1 + 0.1) = 5 m/s², a constant (no terminal velocity, unlike with a resistor).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-magnetism-emi-109","question":"A square loop of side 10 cm and resistance 0.1 Ω is pulled at a constant 2 m/s straight through a region of uniform magnetic field 0.5 T (perpendicular to the loop) that is 30 cm wide. The total heat produced in the loop during its passage is:","options":["0.03 J","0.01 J","0.005 J","0.02 J"],"answer":1,"explanation":"An emf Bav = 0.1 V (current 1 A, power 0.1 W) exists only while the loop is entering or leaving, 0.05 s each. While wholly inside, the flux is constant and there is no current. Heat = 0.1 × 0.1 = 0.01 J.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-magnetism-emi-110","question":"A long solenoid with 1000 turns per metre and cross-section 10 cm² has a 100-turn coil wound tightly round its middle. The mutual inductance of the pair is about:","options":["1.26 × 10⁻⁴ H","1.26 × 10⁻⁷ H","1.26 × 10⁻² H","4 × 10⁻⁵ H"],"answer":0,"explanation":"A current I in the solenoid gives B = μ₀n₁I inside, so the flux linkage with the coil is N₂μ₀n₁IA. M = μ₀n₁N₂A = 4π × 10⁻⁷ × 1000 × 100 × 10⁻³ ≈ 1.26 × 10⁻⁴ H.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-magnetism-emi-111","question":"The magnetic energy density in a region where the magnetic field is 1 T (in vacuum) is about:","options":["1 J/m³","8 × 10⁵ J/m³","4 × 10⁻⁷ J/m³","4 × 10⁵ J/m³"],"answer":3,"explanation":"u = B²/(2μ₀) = 1/(2 × 4π × 10⁻⁷) ≈ 4 × 10⁵ J/m³. Strong magnetic fields store large energies, which is why superconducting magnets 'quench' violently.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-magnetism-emi-112","question":"An inductor and a resistor (time constant τ = L/R) are connected to an ideal battery at t = 0. The energy stored in the inductor reaches one-quarter of its final value at:","options":["τ ln(4/3)","τ ln 4","τ/4","τ ln 2"],"answer":3,"explanation":"U = ½Li², so U = U_max/4 when i = I₀/2. i = I₀(1 − e^(−t/τ)) = I₀/2 gives t = τ ln 2.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-magnetism-emi-113","question":"Two ideal inductors, 1 H and 2 H (no resistance, no mutual coupling), are connected in parallel, and the combination is connected in series with a resistor to a battery. Long after the switch is closed, the currents in the 1 H and 2 H inductors are in the ratio:","options":["1 : 1","1 : 2","2 : 1","1 : 4"],"answer":2,"explanation":"The parallel inductors always share the same voltage, L₁di₁/dt = L₂di₂/dt. Starting from zero currents, L₁i₁ = L₂i₂ at all times, so i₁ : i₂ = L₂ : L₁ = 2 : 1. Their zero resistance means nothing else decides the split.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-magnetism-emi-114","question":"In an ideal LC circuit the capacitor's maximum charge is Q₀. When the energy is shared equally between the capacitor and the inductor, the charge on the capacitor is:","options":["Q₀/2","Q₀/√2","Q₀/4","Q₀/√3"],"answer":1,"explanation":"Total energy Q₀²/2C. Equal sharing means q²/2C = Q₀²/4C, so q = Q₀/√2.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-magnetism-emi-115","question":"A sinusoidal current of peak value I₀ is passed through an ideal half-wave rectifier, so that only the positive half-cycles flow. The rms value of the resulting current is:","options":["I₀/2","I₀/√2","I₀/π","I₀/(2√2)"],"answer":0,"explanation":"Over a full period, i² averages to (I₀²/2) during the conducting half and 0 during the other, i.e. I₀²/4 overall. So I_rms = I₀/2. (The average value is I₀/π.)","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-magnetism-emi-116","question":"A series R–L branch and a series R–C branch are connected in parallel across an AC source. The resistances are equal to R, and at the source frequency X_L = X_C = R. The impedance of the whole combination is:","options":["R, purely resistive","R√2, inductive","R/√2, capacitive","2R, purely resistive"],"answer":0,"explanation":"Each branch has impedance R√2, with the current lagging by 45° in the RL branch and leading by 45° in the RC branch. The admittances (1/R√2)(cos 45° ∓ j sin 45°) add to 1/R with no reactive part. So Z = R and the source current is in phase with the voltage.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-magnetism-emi-117","question":"A straight wire of length √3d carries a current I. Point P lies at a perpendicular distance d from the wire, opposite ONE END of it. The magnetic field at P is:","options":["μ₀I/(8πd)","μ₀I/(4πd)","√3μ₀I/(4πd)","√3μ₀I/(8πd)"],"answer":3,"explanation":"For a finite wire, B = (μ₀I/4πd)(sin θ₁ + sin θ₂), with angles measured from the perpendicular. Here θ₁ = 0 and tan θ₂ = √3d/d, so θ₂ = 60°. B = (μ₀I/4πd)(√3/2) = √3μ₀I/(8πd).","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-magnetism-emi-118","question":"A copper strip 0.1 mm thick (in the direction of B) carries 10 A along its length and lies in a perpendicular magnetic field of 1 T. Copper has 8.5 × 10²⁸ free electrons per m³ (e = 1.6 × 10⁻¹⁹ C). The Hall voltage across the width of the strip is about:","options":["0.74 μV","74 μV","7.4 μV","7.4 mV"],"answer":2,"explanation":"In equilibrium eE_H = ev_dB, and I = nev_d(wt). So V_H = E_H w = IB/(net) = 10 × 1/(8.5 × 10²⁸ × 1.6 × 10⁻¹⁹ × 10⁻⁴) ≈ 7.4 × 10⁻⁶ V. Metals give tiny Hall voltages because n is huge.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-magnetism-emi-119","question":"At a certain place, a dip needle shows an apparent dip of 45° when its plane of rotation is in one vertical plane, and also 45° when it is in the vertical plane at right angles to the first. The true angle of dip is about:","options":["45°","35.3°","54.7°","63.4°"],"answer":1,"explanation":"In a plane at angle α to the meridian, tan δ′ = tan δ/cos α. For two perpendicular planes, cot²δ₁ + cot²δ₂ = cot²δ. So cot²δ = 1 + 1 = 2, tan δ = 1/√2 and δ ≈ 35.3°.","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-magnetism-emi-120","question":"A long solenoid carries a steady current; the magnetic field deep inside it, near the middle, is B. The field on the axis at one of its ends is about:","options":["B","B/2","2B","zero"],"answer":1,"explanation":"Imagine a second identical semi-infinite solenoid joined on: together they make an infinitely long one with field B at the joint, shared equally by symmetry. So each end alone contributes B/2.","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-magnetism-emi-121","question":"A series LCR circuit is driven at a frequency far ABOVE its resonant frequency. The circuit then behaves mainly like:","options":["an inductor, with the current lagging the voltage","a capacitor, with the current leading the voltage","a pure resistor","an open circuit with no current"],"answer":0,"explanation":"Above resonance X_L = ωL exceeds X_C = 1/ωC, and at very high frequencies X_C → 0 while X_L grows. The net reactance is inductive, so the current lags the applied voltage (and becomes small).","difficulty":"moderate","source":"JEE Main"},
  {"id":"phy-magnetism-emi-122","question":"A uniform magnetic field of 0.1 T fills the region on one side of a plane boundary, parallel to the boundary. A proton (q/m = 10⁸ C/kg) enters the field region moving perpendicular to the field, its velocity making 30° with the boundary plane, and the magnetic force on it initially turns it back towards the boundary. The time it spends in the field is about:","options":["5.2 × 10⁻⁸ s","5.2 × 10⁻⁷ s","3.1 × 10⁻⁷ s","1.05 × 10⁻⁷ s"],"answer":3,"explanation":"The proton moves on a circle with ω = qB/m = 10⁷ rad/s. Turning back towards the boundary, it re-crosses after the chord makes equal angles with the boundary, i.e. after an arc of 2 × 30° = 60°. Time = (π/3)/ω ≈ 1.05 × 10⁻⁷ s (it would be 300° if bent the other way).","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-magnetism-emi-123","question":"A coil of N turns and area A rotates with constant angular speed ω in a uniform magnetic field B, about an axis perpendicular to the field. The average emf induced during the half rotation that starts when the plane of the coil is perpendicular to B is:","options":["NBAω/√2","NBAω","2NBAω/π","zero"],"answer":2,"explanation":"Over this half turn the flux changes from +NBA to −NBA in time π/ω. Average emf = ΔΦ/Δt = 2NBA/(π/ω) = 2NBAω/π ≈ 0.64 of the peak value.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-magnetism-emi-124","question":"A thin flat spiral of N closely and evenly spaced turns, with inner radius a and outer radius b, carries a current I. The magnetic field at its centre is:","options":["μ₀NI/[2(b − a)]","μ₀NI/(a + b)","μ₀NI ln(b/a)/[2(b − a)]","μ₀NI(b − a)/(2ab)"],"answer":2,"explanation":"There are N/(b − a) turns per unit radial width, so a ring of width dr gives dB = μ₀I N dr/[2r(b − a)]. Integrating from a to b gives μ₀NI ln(b/a)/[2(b − a)].","difficulty":"very-hard","source":"JEE Advanced pattern"},
  {"id":"phy-magnetism-emi-125","question":"According to the Bohr model, the magnetic moment of the electron in the first orbit of the hydrogen atom is about (e = 1.6 × 10⁻¹⁹ C, h = 6.63 × 10⁻³⁴ J s, mₑ = 9.1 × 10⁻³¹ kg):","options":["1.9 × 10⁻²³ A m²","9.3 × 10⁻²⁴ A m²","4.6 × 10⁻²⁴ A m²","9.3 × 10⁻²⁷ A m²"],"answer":1,"explanation":"M = (e/2m)L with L = h/2π in the first orbit, so M = eh/(4πm) = 1.6 × 10⁻¹⁹ × 6.63 × 10⁻³⁴/(4π × 9.1 × 10⁻³¹) ≈ 9.3 × 10⁻²⁴ A m², the Bohr magneton.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-magnetism-emi-126","question":"A loudspeaker's voice coil has 50 turns of radius 1 cm and sits in a radial magnetic field of 1 T (the field is perpendicular to the wire everywhere). When it carries 0.2 A, the axial force on the coil is about:","options":["0.63 N","0.1 N","6.3 N","0.063 N"],"answer":0,"explanation":"Each element of wire is perpendicular to B, so F = BIL with total length L = N × 2πr = 50 × 0.0628 = 3.14 m. F = 1 × 0.2 × 3.14 ≈ 0.63 N, directed along the axis.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-magnetism-emi-127","question":"A point charge of 1 μC moves at 10⁶ m/s. The magnitude of the magnetic field it produces at a point 1 cm away, in the direction perpendicular to its velocity, is:","options":["1 × 10⁻⁷ T","1 × 10⁻⁵ T","1 × 10⁻¹ T","1 × 10⁻³ T"],"answer":3,"explanation":"For a slowly moving charge (v ≪ c), B = (μ₀/4π)qv sin θ/r² = 10⁻⁷ × 10⁻⁶ × 10⁶/(10⁻²)² = 10⁻³ T.","difficulty":"hard","source":"JEE Main · JEE Advanced"},
  {"id":"phy-magnetism-emi-128","question":"The primary of an IDEAL transformer is connected to an AC supply, while its secondary is left open (no load). The current in the primary is:","options":["equal to the turns ratio times the full-load secondary current","the same as when a full load is connected","infinite, since the primary has no resistance","negligibly small, being only the magnetising current through a very large inductive reactance"],"answer":3,"explanation":"With no load, the primary behaves as a pure inductor of very large inductance; the back emf almost equals the applied voltage, so only a tiny magnetising current (lagging by 90°, consuming no average power) flows. A load on the secondary draws a corresponding extra current in the primary.","difficulty":"very-hard","source":"JEE Advanced pattern"},
];

export default questions;
